/**
 * Generate test fixtures/vectors.json to pin PRNG wire format (I3).
 * This script creates test vectors for cross-implementation conformance.
 */

// Minimal reimplementation of the PRNG functions to generate vectors
// This must be kept in sync with src/core/fountain/prng.ts

function splitmix32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x9e3779b9) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 16), 0x21f0aaad);
    t = Math.imul(t ^ (t >>> 15), 0x735a2d97);
    return ((t ^ (t >>> 15)) >>> 0) / 4294967296;
  };
}

function packetSeed(streamId, blockIndex, seq) {
  let h = streamId >>> 0;
  h = (Math.imul(h ^ (blockIndex >>> 0), 0x85ebca6b) >>> 0) ^ (h >>> 13);
  h = (Math.imul(h ^ (seq >>> 0), 0xc2b2ae35) >>> 0) ^ (h >>> 16);
  return h >>> 0;
}

function makeDegreeTable(k, cap) {
  const hi = Math.min(cap, k);
  let total = 0;
  for (let d = 1; d <= hi; d++) total += 1 / d;
  const cum = new Float64Array(hi);
  let acc = 0;
  for (let d = 1; d <= hi; d++) {
    acc += 1 / d / total;
    cum[d - 1] = acc;
  }
  return cum;
}

function sampleDegree(cum, r) {
  let lo = 0;
  let hi = cum.length - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (cum[mid] < r) lo = mid + 1;
    else hi = mid;
  }
  return lo + 1;
}

function deriveIndices(streamId, blockIndex, seq, k, degreeTable) {
  const rnd = splitmix32(packetSeed(streamId, blockIndex, seq));
  const d = Math.min(sampleDegree(degreeTable, rnd()), k);

  const pool = new Int32Array(k);
  for (let i = 0; i < k; i++) pool[i] = i;
  const out = new Int32Array(d);
  for (let i = 0; i < d; i++) {
    const j = i + Math.floor(rnd() * (k - i));
    const tmp = pool[i];
    pool[i] = pool[j];
    pool[j] = tmp;
    out[i] = pool[i];
  }
  return out;
}

// Generate test vectors
const K = 768;
const DEGREE_CAP = 64;

const vectors = {
  metadata: {
    description: "PRNG wire format test vectors for I3 conformance (§14.3)",
    version: 1,
    generatedAt: new Date().toISOString()
  },
  packetSeed: [
    // Basic cases from tests
    { inputs: [1, 1, 1], output: packetSeed(1, 1, 1) },
    { inputs: [1, 1, 2], output: packetSeed(1, 1, 2) },
    { inputs: [0xdeadbeef, 3, 42], output: packetSeed(0xdeadbeef, 3, 42) },
    { inputs: [0xabcdef, 0, 0], output: packetSeed(0xabcdef, 0, 0) },
    // Boundary cases
    { inputs: [0, 0, 0], output: packetSeed(0, 0, 0) },
    { inputs: [0xffffffff, 0xffffff, 0xffffff], output: packetSeed(0xffffffff, 0xffffff, 0xffffff) },
    { inputs: [0x80000000, 1, 0x7fffff], output: packetSeed(0x80000000, 1, 0x7fffff) },
    // Additional cases
    { inputs: [5, 2, 9], output: packetSeed(5, 2, 9) },
    { inputs: [0x12345678, 0x9abcdef, 0xfedcba], output: packetSeed(0x12345678, 0x9abcdef, 0xfedcba) },
  ],
  splitmix32: [
    // First 5 outputs for various seeds
    { seed: 0, outputs: (() => { const gen = splitmix32(0); return Array.from({length: 5}, () => gen()); })() },
    { seed: 1, outputs: (() => { const gen = splitmix32(1); return Array.from({length: 5}, () => gen()); })() },
    { seed: 0xdeadbeef, outputs: (() => { const gen = splitmix32(0xdeadbeef); return Array.from({length: 5}, () => gen()); })() },
    { seed: 0x9e3779b9, outputs: (() => { const gen = splitmix32(0x9e3779b9); return Array.from({length: 5}, () => gen()); })() },
    { seed: 0xffffffff, outputs: (() => { const gen = splitmix32(0xffffffff); return Array.from({length: 5}, () => gen()); })() },
  ],
  deriveIndices: [
    // Cases from the tests
    {
      inputs: { streamId: 0xdeadbeef, blockIndex: 3, seq: 42, k: K, degreeCap: DEGREE_CAP },
      outputs: Array.from(deriveIndices(0xdeadbeef, 3, 42, K, makeDegreeTable(K, DEGREE_CAP)))
